[legend]
# stairs: ^ > v < climb north/east/south/west, n e s w descend
> = stairs dir=up face=E
^ = stairs dir=up face=N
e = stairs dir=down face=E
n = stairs dir=down face=N
s = stairs dir=down face=S
w = stairs dir=down face=W

